{
  "notable_events": [
    "The flood riots began after the spring thaw swelled the Silverflow, destroying the old stone bridge.",
    "The village mill was damaged by floodwaters, halting grain grinding for weeks.",
    "Duke Aldric sent soldiers to restore order, but tensions remained high.",
    "The Restless Fox inn became a refuge for displaced families."
  ],
  "texture_line": "Mud and the smell of wet ash clung to the village as the river's roar drowned out all but the loudest shouts."
}

